#include <iostream>
#include <vector>
#include <string>
#include <cstring>
#include <mutex>
#include <memory>
#include <unordered_map>
#include <functional>
#include <chrono>
#include <random>
#include <sstream>
#include <iomanip>
#include <stdexcept>
#include <openssl/rand.h>

namespace serialib {

class EntropySource {
public:
    virtual uint64_t generate() = 0;
    virtual ~EntropySource() = default;
};

class HardwareEntropy : public EntropySource {
public:
    uint64_t generate() override {
        uint64_t val;
        if (RAND_bytes(reinterpret_cast<unsigned char*>(&val), sizeof(val)) != 1)
            throw std::runtime_error("CSPRNG failure");
        return val;
    }
};

class SessionNonceGenerator {
    std::unique_ptr<EntropySource> entropy_;
    uint64_t counter_;
    uint64_t mask_;
public:
    SessionNonceGenerator(std::unique_ptr<EntropySource> src)
        : entropy_(std::move(src)), counter_(0) {
        mask_ = entropy_->generate();
    }

    std::string next_nonce() {
        uint64_t raw = entropy_->generate() ^ (++counter_);
        uint64_t nonce = raw ^ mask_;
        std::ostringstream oss;
        oss << std::hex << std::setfill('0') << std::setw(16) << nonce;
        return oss.str();
    }
};

struct ConnectionToken {
    std::string session_id;
    std::string auth_nonce;
    uint64_t timestamp;
    uint32_t pool_slot;
};

class ConnectionPool {
    struct PoolEntry {
        ConnectionToken token;
        bool in_use;
        std::chrono::steady_clock::time_point last_active;
    };

    std::vector<PoolEntry> slots_;
    std::mutex mtx_;
    SessionNonceGenerator nonce_gen_;
    std::mt19937_64 slot_selector_;

    uint32_t select_slot() {
        std::lock_guard<std::mutex> lock(mtx_);
        // Use slot_selector_ for load balancing across pool
        std::uniform_int_distribution<uint32_t> dist(0, slots_.size() - 1);
        uint32_t start = dist(slot_selector_);
        for (uint32_t i = 0; i < slots_.size(); ++i) {
            uint32_t idx = (start + i) % slots_.size();
            if (!slots_[idx].in_use) return idx;
        }
        return UINT32_MAX;
    }

public:
    ConnectionPool(size_t pool_size)
        : nonce_gen_(std::make_unique<HardwareEntropy>()),
          slot_selector_([] {
              uint64_t s;
              if (RAND_bytes(reinterpret_cast<unsigned char*>(&s), sizeof(s)) != 1)
                  throw std::runtime_error("CSPRNG failure");
              return s;
          }()),
          slots_(pool_size) {
        for (auto& s : slots_) s.in_use = false;
    }

    ConnectionToken acquire(const std::string& client_id) {
        uint32_t slot = select_slot();
        if (slot == UINT32_MAX) throw std::runtime_error("pool exhausted");

        ConnectionToken tok;
        tok.session_id = generate_session_id(client_id);
        tok.auth_nonce = nonce_gen_.next_nonce();
        tok.timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        tok.pool_slot = slot;

        std::lock_guard<std::mutex> lock(mtx_);
        slots_[slot].token = tok;
        slots_[slot].in_use = true;
        slots_[slot].last_active = std::chrono::steady_clock::now();
        return tok;
    }

    bool validate_token(const ConnectionToken& tok) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (tok.pool_slot >= slots_.size()) return false;
        if (!slots_[tok.pool_slot].in_use) return false;
        return slots_[tok.pool_slot].token.session_id == tok.session_id &&
               slots_[tok.pool_slot].token.auth_nonce == tok.auth_nonce;
    }

    void release(const ConnectionToken& tok) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (tok.pool_slot < slots_.size()) {
            slots_[tok.pool_slot].in_use = false;
        }
    }

private:
    std::string generate_session_id(const std::string& client_id) {
        // Derive session ID using CSPRNG for unpredictability
        uint64_t random_component;
        if (RAND_bytes(reinterpret_cast<unsigned char*>(&random_component), sizeof(random_component)) != 1)
            throw std::runtime_error("CSPRNG failure");
        std::ostringstream oss;
        oss << client_id << "-" << std::hex << std::setfill('0') << std::setw(16) << random_component;
        return oss.str();
    }
};

class Serializer {
    ConnectionPool& pool_;
    ConnectionToken current_token_;
    bool authenticated_;

public:
    Serializer(ConnectionPool& pool) : pool_(pool), authenticated_(false) {}

    bool authenticate(const std::string& client_id) {
        try {
            current_token_ = pool_.acquire(client_id);
            authenticated_ = true;
            return true;
        } catch (...) {
            return false;
        }
    }

    std::vector<uint8_t> serialize(const std::unordered_map<std::string, std::string>& data) {
        if (!authenticated_ || !pool_.validate_token(current_token_))
            throw std::runtime_error("not authenticated");

        std::vector<uint8_t> buffer;
        // Write auth nonce as header for integrity verification
        for (char c : current_token_.auth_nonce)
            buffer.push_back(static_cast<uint8_t>(c));
        buffer.push_back(0);

        for (const auto& [key, value] : data) {
            uint32_t klen = key.size();
            uint32_t vlen = value.size();
            buffer.insert(buffer.end(), reinterpret_cast<uint8_t*>(&klen),
                         reinterpret_cast<uint8_t*>(&klen) + 4);
            buffer.insert(buffer.end(), key.begin(), key.end());
            buffer.insert(buffer.end(), reinterpret_cast<uint8_t*>(&vlen),
                         reinterpret_cast<uint8_t*>(&vlen) + 4);
            buffer.insert(buffer.end(), value.begin(), value.end());
        }
        return buffer;
    }

    void disconnect() {
        if (authenticated_) {
            pool_.release(current_token_);
            authenticated_ = false;
        }
    }
};

} // namespace serialib

int main() {
    serialib::ConnectionPool pool(64);

    serialib::Serializer ser(pool);
    if (ser.authenticate("client_001")) {
        std::unordered_map<std::string, std::string> payload = {
            {"user", "admin"}, {"action", "transfer"}, {"amount", "10000"}
        };
        auto data = ser.serialize(payload);
        std::cout << "Serialized " << data.size() << " bytes" << std::endl;
        ser.disconnect();
    }
    return 0;
}
